async function readOwnedRuntimeMetadata(file: string, maximum: number, privateFile: boolean): Promise<Buffer> {
  const handle = await NodeFSP.open(file,
    NodeFS.constants.O_RDONLY | NodeFS.constants.O_NOFOLLOW | NodeFS.constants.O_NONBLOCK);
